import 'package:youtube_explode_dart/youtube_explode_dart.dart'; import 'dart:io'; void main() async { final yt = YoutubeExplode(); try { final manifest = await yt.videos.streamsClient.getManifest('dQw4w9WgXcQ', ytClients: [YoutubeApiClient.android]); final url = manifest.audioOnly.withHighestBitrate().url.toString(); print('Testing URL: ' + url); final client = HttpClient(); final request = await client.getUrl(Uri.parse(url)); request.headers.set('user-agent', 'com.google.android.youtube/18.36.39 (Linux; U; Android 13; en_US) gzip'); final response = await request.close(); print('Response status: ' + response.statusCode.toString()); yt.close(); } catch (e) { print('Error: ' + e.toString()); } }
